name: Test Count Badge

on:
  push:
    branches: [main]
  pull_request:
    branches: [main]
  schedule:
    - cron: '0 0 * * *'  # daily

jobs:
  test-count:
    runs-on: ubuntu-latest

    steps:
      - name: Checkout repository
        uses: actions/checkout@v4

      - name: Set up Python
        uses: actions/setup-python@v5
        with:
          python-version: '3.11'

      - name: Install dependencies
        run: |
          python -m pip install --upgrade pip
          if [ -f requirements.txt ]; then pip install -r requirements.txt; fi

      - name: Count test functions
        run: |
          python count_tests.py

      - name: Update README badge
        uses: actions/github-script@v6
        with:
          script: |
            const fs = require('fs');
            const path = '.github/test-stats.json';
            if (!fs.existsSync(path)) {
              console.log('test-stats.json not found');
              process.exit(1);
            }
            const data = JSON.parse(fs.readFileSync(path, 'utf8'));
            const badge = `![Test Count](https://img.shields.io/badge/tests-${data.count}-brightgreen)`;
            const readmePath = 'README.md';
            let readme = fs.readFileSync(readmePath, 'utf8');
            const badgeRegex = /!\[Test Count\]\(.*\)/;
            if (badgeRegex.test(readme)) {
              readme = readme.replace(badgeRegex, badge);
            } else {
              const lines = readme.split('\n');
              const badgeLineIndex = lines.findIndex(line => line.includes('!['));
              if (badgeLineIndex !== -1) {
                lines.splice(badgeLineIndex + 1, 0, badge);
              } else {
                lines.unshift(badge);
              }
              readme = lines.join('\n');
            }
            fs.writeFileSync(readmePath, readme);
            console.log('Badge updated');

        env:
          GITHUB_TOKEN: ${{ secrets.GITHUB_TOKEN }}

      - name: Commit changes
        uses: stefanzweifel/git-auto-commit-action@v5
        with:
          commit_message: 'Update test count badge'
          file_pattern: 'README.md .github/test-stats.json'
          push_options: '--force'
